// Run separately from builds: node client/tests/browser-artifacts.mjs
// Uses a temporary project generated by the real sandbox; no live model calls.
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
const profile = await mkdtemp('/tmp/chart-browser-');
const port = 19294;
const chrome = spawn(process.env.CHROME_PATH || '/opt/google/chrome/chrome', ['--headless','--no-sandbox','--disable-gpu','--no-proxy-server',`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,'--window-size=1440,1000','about:blank'], {stdio:'ignore'});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
let ws;
try {
 let tabs;
 for(let i=0;i<60;i++){try{tabs=await(await fetch(`http://127.0.0.1:${port}/json`)).json();break;}catch{await sleep(100);}}
 ws=new WebSocket(tabs.find(t=>t.type==='page'&&t.url==='about:blank').webSocketDebuggerUrl);
 await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
 let seq=0;const pending=new Map();const errors=[];
 ws.onmessage=({data})=>{const m=JSON.parse(data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(pending.has(m.id)){pending.get(m.id)(m.result);pending.delete(m.id);}};
 const call=(method,params={})=>new Promise(r=>{const id=++seq;pending.set(id,r);ws.send(JSON.stringify({id,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);return r.result.value;};
 await call('Runtime.enable');
 await call('Page.navigate',{url:process.env.APP_URL || 'http://127.0.0.1:3001/'});await sleep(1500);

 await call('Network.enable');
 const externals=[];const previous=ws.onmessage;
 ws.onmessage=event=>{const message=JSON.parse(event.data);if(message.method==='Network.requestWillBeSent'&&/^https?:/.test(message.params.request.url)&&!/^http:\/\/(localhost|127\.0\.0\.1)/.test(message.params.request.url))externals.push(message.params.request.url);previous(event);};
 const setup = `(async()=>{window.wait=ms=>new Promise(r=>setTimeout(r,ms));window.check=(v,label)=>{if(!v)throw Error(label+' | '+document.body.innerText.slice(0,1800))};
 window.until=async(fn,label)=>{for(let i=0;i<200;i++){if(fn())return fn();await wait(50);}throw Error(label+' | '+document.body.innerText.slice(0,1800))};
 window.button=(text,root=document)=>[...root.querySelectorAll('button')].find(b=>b.textContent.trim()===text);
 window.graph=()=>document.querySelector('.generated-artifact .js-plotly-plot');
 window.ready=async()=>{await until(()=>graph()?._fullLayout&&!document.querySelector('.generated-artifact [role="status"]'),'plot not ready');await wait(200);};
 window.openSaved=async name=>{button('Saved Analyses').click();const card=await until(()=>[...document.querySelectorAll('.analysis-entry')].find(b=>b.textContent.includes('Controlled '+name)),'Saved artifact missing: '+name);card.click();await wait(100);};
 (await until(()=>[...document.querySelectorAll('aside .nav-item')].find(b=>b.textContent==='Artifact delivery verification'),'Test project missing')).click();})();`;
 await evaluate(setup);
 await sleep(300);
 await evaluate(`(async()=>{(await until(()=>[...document.querySelectorAll('aside .nav-item')].find(b=>b.textContent==='Customers'),'Customers missing')).click();await wait(200);})();`);
 const shots='/tmp/v1-artifact-visuals';await import('node:fs/promises').then(fs=>fs.mkdir(shots,{recursive:true}));
 const screenshot=async name=>{await evaluate(`(()=>{const body=document.querySelector('.workspace-body'),plot=document.querySelector('.artifact-plot-scroll,.artifact-image-frame');if(body&&plot)body.scrollTop+=plot.getBoundingClientRect().top-body.getBoundingClientRect().top-15;})();`);await sleep(100);await writeFile(shots+'/'+name+'.png',Buffer.from((await call('Page.captureScreenshot',{format:'png'})).data,'base64'));};
 for(const name of ['line','scatter','histogram','box','heatmap','pie','dense','png','empty','unsupported','capture_failed']){
  console.log(await evaluate(`(async()=>{await openSaved('${name}');
   if('${name}'==='png')await until(()=>document.querySelector('.artifact-image-frame img')?.naturalWidth>0,'PNG missing');
   else if(['empty','unsupported','capture_failed'].includes('${name}'))await until(()=>document.querySelector('.generated-artifact .chart-notice'),'Missing explanation');
   else await ready();
   check(document.querySelector('.workspace-heading').textContent.includes('Customers'),'Browsing context lost');check(document.querySelector('.workspace-heading').textContent.includes('artifact_fixture.csv'),'Source lost');
   check(document.querySelector('.calculation-details').textContent.includes('run code'),'Run-code provenance lost');check(!document.querySelector('.calculation-details').open,'Calculation not collapsed');
   const download=document.querySelector('.artifact-download');check(download,'Download missing');const response=await fetch(download.href);check(response.ok,'Download broken');check(response.headers.get('content-disposition').includes('attachment'),'HTML not attachment');
   if('${name}'==='dense'){check(graph().data[0].x.length===25,'Data omitted');check(document.querySelector('.artifact-plot-scroll').scrollWidth>document.querySelector('.artifact-plot-scroll').clientWidth,'Dense labels not scrollable');}
   return {example:'${name}',download:true,provenance:true};})();`));
  await screenshot(name+'-desktop');
  await call('Emulation.setDeviceMetricsOverride',{width:390,height:1000,deviceScaleFactor:1,mobile:false});await sleep(250);
  console.log(await evaluate(`(()=>{check(document.documentElement.scrollWidth<=390,'Page overflow');if(graph())check(graph()._fullLayout.width>=300,'Plot too small');return {narrow:'${name}'};})();`));
  await screenshot(name+'-narrow');
  await call('Emulation.clearDeviceMetricsOverride');await sleep(150);
 }
 console.log(await evaluate(`(async()=>{await openSaved('line');await ready();const first=graph()._fullLayout.width;
 const toggle=document.querySelector('[title="Collapse Chat Panel"]')||document.querySelector('[title="Collapse Chat"]')||[...document.querySelectorAll('button')].find(b=>b.title.toLowerCase().includes('collapse')&&b.title.toLowerCase().includes('chat'));
 check(toggle,'Collapse control missing');toggle.click();await wait(400);check(graph()._fullLayout.width>first,'Chat collapse did not resize chart');
 return {collapseResize:true,before:first,after:graph()._fullLayout.width};})();`));
 // Exercise panel dragging with actual pointer input.
 const handle=await evaluate(`(()=>{const r=document.querySelector('.sidebar-resizer.left').getBoundingClientRect();return {x:r.x+3,y:r.y+100};})()`);
 await call('Input.dispatchMouseEvent',{type:'mouseMoved',...handle});await call('Input.dispatchMouseEvent',{type:'mousePressed',...handle,button:'left',clickCount:1});
 await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:handle.x+80,y:handle.y,button:'left',buttons:1});await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:handle.x+80,y:handle.y,button:'left',clickCount:1});await sleep(300);
 console.log(await evaluate(`({resizedWidth:graph()._fullLayout.width})`));await screenshot('line-chat-collapsed-resized');
 // Reload, then use actual saved chat history to reopen the artifact.
 await call('Page.reload');await sleep(1500);await evaluate(setup);await sleep(100);
 console.log(await evaluate(`(async()=>{
 (await until(()=>[...document.querySelectorAll('aside .nav-item')].find(b=>b.textContent==='Artifact delivery verification'),'Project after reload')).click();await wait(150);
 button('Past chats').click();const card=await until(()=>[...document.querySelectorAll('.right-panel .chat-turn')].find(row=>row.textContent.includes('Controlled line generated'))?.querySelector('.chat-result-card'),'Past-chat artifact missing');card.click();await ready();check(graph().data.length===2,'Restored figure lost series');
 check(!document.querySelector('.right-panel img[src^="data:image/png;base64,"]'),'HTML interpreted as PNG');const noChart=[...document.querySelectorAll('.right-panel .chat-turn')].find(row=>row.textContent.includes('Controlled no_chart generated'));check(noChart&&!noChart.querySelector('.chat-result-card'),'Empty output has broken Open result');return {reload:true,pastChatOpen:true,multipleSeries:true};})();`));
 // Simulate only delivery of a new chat reply; artifacts themselves come from the real saved execution.
 console.log(await evaluate(`(async()=>{
 const api='http://127.0.0.1:8001/api/v1';const projects=await(await fetch(api+'/projects/')).json(),project=projects.find(p=>p.name==='Artifact delivery verification');
 const snapshots=await(await fetch(api+'/projects/'+project.id+'/analyses')).json();const capture=snapshots.find(s=>s.question==='Controlled line');
 const original=window.fetch;window.fetch=async(...args)=>{if(String(args[0]).endsWith('/chat/message/stream'))return new Response(JSON.stringify({stage:'completed',result:{id:capture.id,role:'assistant',content:'Controlled live delivery',artifacts:capture.artifacts,calculation:capture.calculation,question:capture.question}})+'\\n');return original(...args);};
 button('Back to current chat').click();await wait(100);const input=document.querySelector('[aria-label="Question for the analyst"]');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(input,'Controlled delivery');input.dispatchEvent(new Event('input',{bubbles:true}));await wait(100);input.form.requestSubmit();
 const card=await until(()=>[...document.querySelectorAll('.right-panel .chat-turn')].find(row=>row.textContent.includes('Controlled live delivery'))?.querySelector('.chat-result-card'),'Live artifact card missing');card.click();await ready();return {chatOnlyArtifactOpen:true};})();`));
 await call('Network.emulateNetworkConditions',{offline:true,latency:0,downloadThroughput:0,uploadThroughput:0});
 console.log(await evaluate(`(async()=>{await window.Plotly.relayout(graph(),{'xaxis.autorange':true,'yaxis.autorange':true});check(graph()._fullData.length===2,'Offline interaction failed');return {offlinePlotlyInteraction:true};})()`));
 await call('Network.emulateNetworkConditions',{offline:false,latency:0,downloadThroughput:-1,uploadThroughput:-1});
 if(externals.length)throw Error('External requests: '+externals.join(','));
 if(errors.length)throw Error(errors.join(','));
 console.log('Artifact browser checks passed. Screenshots: '+shots);
}finally{ws?.close();chrome.kill();await sleep(100);await rm(profile,{recursive:true,force:true}).catch(()=>{});}
